effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _resolution acTamanhoDaTela
vec4 u_xlat0;
vec4 u_xlat1;
bvec2 u_xlatb1;
vec4 u_xlat2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
float u_xlat6;
vec2 u_xlat13;
float u_xlat18;
void main()
{
    u_xlat0.xyz = vec3(_scale, _size, _scale) * vec3(10.0, 10.0, 5.0);
    u_xlat18 = 3.14159203 / u_xlat0.x;
    u_xlat6 = u_xlat0.y / u_xlat0.x;
    u_xlat1.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat1.xy = u_xlat1.xy * _resolution.xy;
    u_xlat13.xy = vec2(u_xlat18) * u_xlat1.xy;
    u_xlat13.xy = sin(u_xlat13.xy);
    u_xlat13.xy = (-vec2(u_xlat6)) + abs(u_xlat13.xy);
    u_xlat1.xy = u_xlat1.xy / u_xlat0.xx;
    u_xlat1.xy = floor(u_xlat1.xy);
    u_xlat0.xz = u_xlat1.xy * u_xlat0.xx + u_xlat0.zz;
    u_xlat0.xz = u_xlat0.xz / _resolution.xy;
    u_xlat0.xz = u_xlat0.xz + vec2(0.5, 0.5);
    u_xlat2 = texture(inputImg, u_xlat0.xz);
    u_xlat2 = u_xlat13.xxxx * u_xlat2;
    u_xlat1 = u_xlat13.yyyy * u_xlat2;
    u_xlat0.x = _brightness / u_xlat6;
    u_xlat2 = texture(inputImg, acScreenNorm.xy);
    u_xlat0 = u_xlat1 * u_xlat0.xxxx + (-u_xlat2);
    u_xlat0 = vec4(vec4(_blend, _blend, _blend, _blend)) * u_xlat0 + u_xlat2;
    if(int(_use_inner_mask) != 0) {
        u_xlatb1.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb1.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat2 = u_xlat2 * u_xlat5;
        u_xlat2 = u_xlat3 * u_xlat4 + u_xlat2;
        u_xlat1.x = u_xlat4.x * u_xlat2.w;
        fragColor.w = (u_xlatb1.y) ? u_xlat1.x : u_xlat2.w;
        fragColor.xyz = u_xlat2.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
